package main

import (
	"errors"
	"log"

	"github.com/pocketbase/pocketbase"
	"github.com/pocketbase/pocketbase/core"
)

func main() {
	app := pocketbase.New()

	// Register a hook for the "posts" collection that runs before a record is created.
	app.OnRecordBeforeCreateRequest("posts").BindFunc(func(e *core.RecordRequestEvent) error {
		title := e.Record.GetString("title")

		// Reject creation when the title is empty or missing.
		if title == "" {
			return errors.New("Title cannot be empty")
		}

		// Programmatically generate the slug from the title.
		e.Record.Set("slug", core.Slugify(title))

		// Continue the hook execution chain.
		return e.Next()
	})

	if err := app.Start(); err != nil {
		log.Fatal(err)
	}
}

